
.panel {
  margin-top: 9px;
  padding: 8px 10px 9px;
  background: var(--c-surface-raised);
  border: 1px dashed var(--c-border);
  border-radius: 7px;
}

.panel__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
}

.panel__label {
  color: var(--c-text);
  font-size: 12px;
  font-weight: 600;
}

.panel__count {
  color: var(--c-primary);
  font-size: 12px;
  font-weight: 700;

  i {
    color: var(--c-text-muted);
    font-style: normal;
    font-weight: 500;
  }
}

.line {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 4px 6px;
  margin-top: 5px;
}

.line__k {
  flex: 0 0 auto;
  min-width: 30px;
  color: var(--c-text-muted);
  font-size: 10.5px;
}

.line__k--off {
  color: var(--c-danger);
}

.line__k--ok {
  color: var(--c-system);
}

.chip {
  padding: 1px 7px;
  background: var(--c-surface-soft);
  border: 1px dashed var(--c-border);
  border-radius: 999px;
  color: var(--c-text-muted);
  font-size: 11.5px;
}

.chip--ok {
  border: 1px solid var(--c-system);
  background: transparent;
  color: var(--c-system);
  font-weight: 600;
}

.chip--off {
  border: 1px solid var(--c-danger);
  background: transparent;
  color: var(--c-danger);
  text-decoration: line-through;
}

.empty {
  margin-top: 4px;
  color: var(--c-text-muted);
  font-size: 11.5px;
}
