
.bar {
  padding: 8px 12px 9px;
  background: var(--c-surface-raised);
}

.bar__line {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 14px;
  align-items: baseline;
}

.bar__line--second {
  margin-top: 4px;
}

.item {
  font-weight: 600;
}

.item--muted {
  color: var(--c-text-muted);
  font-weight: 500;
}

.k {
  margin-right: 5px;
  color: var(--c-text-muted);
  font-weight: 400;
  font-size: 12px;
}

.stage {
  padding: 1px 8px;
  border: 1px solid var(--c-primary);
  border-radius: 999px;
  color: var(--c-primary);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.04em;
}
