
.panel {
  margin-top: 9px;
  padding: 8px 10px 9px;
  background: var(--c-surface-raised);
  border: 1px solid var(--c-border);
  border-radius: 7px;
}

.panel__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
}

.panel__label {
  color: var(--c-system);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.03em;
}

.panel__owner {
  padding: 0 7px;
  border: 1px solid var(--c-system);
  border-radius: 999px;
  color: var(--c-system);
  font-size: 10.5px;
}

.energy {
  margin-top: 7px;
}

.energy__top {
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.energy__k {
  color: var(--c-text-muted);
  font-size: 11.5px;
}

.energy__v {
  font-size: 19px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  line-height: 1.1;

  i {
    color: var(--c-text-muted);
    font-size: 11px;
    font-style: normal;
    font-weight: 500;
  }

  &.is-low {
    color: var(--c-danger);
  }
}

.energy__pts {
  margin-left: auto;
  color: var(--c-warn);
  font-size: 11.5px;
  font-variant-numeric: tabular-nums;
}

.bar {
  position: relative;
  height: 8px;
  margin-top: 5px;
  background: var(--c-track);
  border-radius: 4px;
}

.bar__fill {
  height: 100%;
  background: linear-gradient(90deg, var(--c-system), var(--c-primary));
  border-radius: 4px;
  transition: width 0.5s ease;
}

.bar__tick {
  position: absolute;
  top: -2px;
  left: 30%;
  width: 1px;
  height: 12px;
  background: rgb(233 229 245 / 26%);

  i {
    position: absolute;
    top: 12px;
    left: 2px;
    color: var(--c-text-muted);
    font-size: 9px;
    font-style: normal;
  }
}

.energy__note {
  margin-top: 11px;
  color: var(--c-warn);
  font-size: 11px;
}

.plates {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 4px 6px;
  margin-top: 12px;
}

.plate {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 6px;
  padding: 2px 7px;
  background: var(--c-surface-soft);
  border-left: 2px solid var(--c-border);
  border-radius: 4px;
  font-size: 11.5px;
}

.plate__name {
  color: var(--c-text);
}

.plate__state {
  color: var(--c-text-muted);
  font-size: 10.5px;
}

.plate--ok {
  border-left-color: var(--c-system);

  .plate__state {
    color: var(--c-system);
  }
}

.plate--warn {
  border-left-color: var(--c-warn);

  .plate__state {
    color: var(--c-warn);
  }
}

.plate--danger {
  border-left-color: var(--c-danger);

  .plate__state {
    color: var(--c-danger);
  }
}

.queue {
  margin-top: 9px;
  padding-top: 7px;
  border-top: 1px dashed var(--c-border);
}

.queue__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  color: var(--c-text-muted);
  font-size: 11.5px;
}

.queue__sum {
  color: var(--c-primary);
}

.queue__empty {
  margin-top: 3px;
  color: var(--c-text-muted);
  font-size: 11px;
}

.row {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 4px;
}

.row__name {
  flex: 0 0 68px;
  font-size: 11.5px;
}

.row__bar {
  flex: 1;
  height: 5px;
  background: var(--c-track);
  border-radius: 3px;
}

.row__fill {
  height: 100%;
  background: var(--c-primary);
  border-radius: 3px;
  transition: width 0.5s ease;
}

.row__num {
  flex: 0 0 auto;
  color: var(--c-text-muted);
  font-size: 10.5px;
  font-variant-numeric: tabular-nums;
}
