
.card {
  padding: 10px 12px 11px;
  background: var(--c-surface-raised);
  border: 1px solid var(--c-border);
  border-left: 3px solid var(--c-border);
  border-radius: 7px;

  &.is-shown {
    border-left-color: var(--c-accent);
    box-shadow: 0 0 0 1px rgb(196 106 156 / 26%);
  }

  &.is-deep .score__value {
    color: var(--c-accent);
  }
}

.card__top {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
}

.card__name {
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 0.03em;
}

.badge {
  margin-left: 6px;
  padding: 0 6px;
  border: 1px solid var(--c-system);
  border-radius: 999px;
  color: var(--c-system);
  font-size: 10px;
  font-weight: 600;
  vertical-align: 2px;
}

.card__seq {
  color: var(--c-text-muted);
  font-size: 11px;
  font-variant-numeric: tabular-nums;
}

.card__seq-note {
  margin-left: 6px;
  color: var(--c-border);
}

.card__score {
  display: flex;
  align-items: baseline;
  gap: 3px;
  margin-top: 2px;
}

.score__value {
  font-size: 26px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  line-height: 1.1;
}

.score__unit {
  color: var(--c-text-muted);
  font-size: 12px;
}

.score__stage {
  margin-left: 8px;
  padding: 0 7px;
  border: 1px solid var(--c-primary);
  border-radius: 999px;
  color: var(--c-primary);
  font-size: 11px;
}

.bar {
  position: relative;
  height: 8px;
  margin: 6px 0 8px;
  background: var(--c-track);
  border-radius: 4px;
}

.bar__fill {
  height: 100%;
  background: linear-gradient(90deg, var(--c-primary), var(--c-accent));
  border-radius: 4px;
  transition: width 0.5s ease;
}

.bar__tick {
  position: absolute;
  top: -2px;
  width: 1px;
  height: 12px;
  background: rgb(233 229 245 / 26%);

  i {
    position: absolute;
    top: 12px;
    left: 2px;
    color: var(--c-text-muted);
    font-size: 9px;
    font-style: normal;
  }

  &--60 {
    left: 60%;
  }

  &--80 {
    left: 80%;
  }
}

.card__rows {
  display: grid;
  gap: 2px;
  margin: 6px 0 0;
}

.row {
  display: flex;
  gap: 8px;
  align-items: baseline;
  font-size: 12.5px;

  dt {
    flex: 0 0 60px;
    color: var(--c-text-muted);
    font-size: 11.5px;
  }

  dd {
    margin: 0;
    min-width: 0;
  }
}

.row__persona {
  color: var(--c-primary);
  font-weight: 700;
}

.row__title {
  color: var(--c-text);
}

.tags {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  margin-top: 8px;
}

.tag {
  padding: 0 7px;
  border: 1px solid var(--c-border);
  border-radius: 999px;
  color: var(--c-text-muted);
  font-size: 10.5px;
}

.tag--shown {
  border-color: var(--c-accent);
  color: var(--c-accent);
  font-weight: 600;
}

.tag--hw {
  border-style: dashed;
}

.tag--ok {
  border-color: var(--c-system);
  color: var(--c-system);
  font-weight: 600;
}

.tag--off {
  border-color: var(--c-danger);
  color: var(--c-danger);
  font-weight: 600;
}
