
.page {
  display: flex;
  align-items: stretch;
  gap: 6px;
}

.slot {
  flex: 1;
  min-width: 0;
}

.nav {
  flex: 0 0 26px;
  padding: 0;
  background: var(--c-surface-raised);
  border: 1px solid var(--c-border);
  border-radius: 7px;
  color: var(--c-primary);
  font-size: 18px;
  line-height: 1;
  cursor: pointer;
  transition: background 0.2s ease;

  &:hover:not(:disabled) {
    background: var(--c-surface-soft);
  }

  &:disabled {
    color: var(--c-border);
    cursor: default;
  }
}

.dots {
  display: flex;
  justify-content: center;
  gap: 5px;
  margin-top: 7px;
}

.dot {
  width: 7px;
  height: 7px;
  padding: 0;
  background: var(--c-track);
  border: none;
  border-radius: 50%;
  cursor: pointer;
  transition:
    background 0.2s ease,
    transform 0.2s ease;

  &--on {
    background: var(--c-accent);
    transform: scale(1.25);
  }
}

.empty {
  padding: 16px 12px;
  background: var(--c-surface-raised);
  border: 1px dashed var(--c-border);
  border-radius: 7px;
  text-align: center;
}

.empty__title {
  color: var(--c-text);
  font-size: 13px;
  font-weight: 600;
}

.empty__hint {
  margin-top: 3px;
  color: var(--c-text-muted);
  font-size: 11.5px;
}
